import json
import re
from typing import Any

from django.contrib.postgres.search import SearchQuery
from django.db import connection
from django.db.models import Q, QuerySet
from django.utils import timezone
from django.utils.dateparse import parse_datetime
from rest_framework.exceptions import ValidationError

from .search_dsl import (
    DEFAULT_SORT,
    SEARCH_FIELD_CONFIG,
    is_datetime_field,
    is_supported_ordering_field,
    normalize_field_name,
)


def _build_filter_clause(filter_data: dict) -> tuple[Q, bool]:
    """Build a Q object for the given filter and track if regex is used."""
    field = filter_data["field"]
    op = filter_data["op"]
    value = filter_data["value"]
    lookup = SEARCH_FIELD_CONFIG[field]["lookup"]
    uses_regex = op == "regex"

    if op == "contains":
        clause = Q(**{f"{lookup}__icontains": value})
    elif op == "not_contains":
        clause = ~Q(**{f"{lookup}__icontains": value})
    elif op == "starts_with":
        clause = Q(**{f"{lookup}__istartswith": value})
    elif op == "ends_with":
        clause = Q(**{f"{lookup}__iendswith": value})
    elif op == "eq":
        clause = Q(**{lookup: value})
    elif op == "in":
        clause = Q(**{f"{lookup}__in": value})
    elif op == "regex":
        clause = Q(**{f"{lookup}__iregex": value})
    elif op in {"gte", "lte", "gt", "lt"}:
        clause = Q(**{f"{lookup}__{op}": value})
    else:
        raise ValidationError(f"Unsupported operator: {op}")

    return clause, uses_regex


def _apply_free_text(
    queryset: QuerySet, q_value: str | None
) -> tuple[QuerySet, list[str]]:
    """Apply free text search using Postgres full-text search when available."""
    if not q_value:
        return queryset, []

    queryset = queryset.exclude(is_external=True)
    tokens = [token for token in re.split(r"\s+", q_value.strip()) if token]

    if connection.vendor == "postgresql":
        search_query = SearchQuery(q_value, config="english", search_type="websearch")
        queryset = queryset.filter(search_vector=search_query)
    else:
        contains_q = Q()
        for token in tokens:
            contains_q &= (
                Q(title__icontains=token)
                | Q(description__icontains=token)
                | Q(location__icontains=token)
            )
        queryset = queryset.filter(contains_q)

    return queryset, tokens


def _build_ordering(sort_config: list[dict[str, str]]) -> list[str]:
    """Convert sort config into Django ordering strings."""
    ordering: list[str] = []
    for sort_item in sort_config or DEFAULT_SORT:
        raw_field = sort_item.get("field")
        if not isinstance(raw_field, str):
            continue

        field = normalize_field_name(raw_field)
        direction = sort_item.get("dir", "asc")
        if not is_supported_ordering_field(field):
            continue
        prefix = "-" if direction == "desc" else ""
        ordering.append(f"{prefix}{SEARCH_FIELD_CONFIG[field]['lookup']}")
    if not ordering:
        ordering = ["start_time"]

    # Add a deterministic tiebreaker so cursor pagination cannot skip equal values.
    if not any(order_field.lstrip("-") == "id" for order_field in ordering):
        id_prefix = "-" if ordering[0].startswith("-") else ""
        ordering.append(f"{id_prefix}id")

    return ordering


def _decode_cursor(cursor_value: str) -> tuple[str, str | None]:
    """Decode cursor values, supporting both legacy and structured formats."""
    try:
        payload = json.loads(cursor_value)
    except (TypeError, ValueError, json.JSONDecodeError):
        return cursor_value, None

    if not isinstance(payload, dict):
        return cursor_value, None

    raw_value = payload.get("value")
    raw_id = payload.get("id")
    if raw_value is None:
        return cursor_value, None

    decoded_value = str(raw_value)
    decoded_id = str(raw_id) if raw_id else None
    return decoded_value, decoded_id


def apply_cursor_filter(
    queryset: QuerySet, ordering: list[str], cursor_value: str | None
) -> QuerySet:
    """Apply cursor-based pagination filter."""
    if not cursor_value or not ordering:
        return queryset

    target_field = None
    descending = False
    for order_field in ordering:
        field_name = order_field.lstrip("-")
        if is_supported_ordering_field(field_name):
            target_field = field_name
            descending = order_field.startswith("-")
            break

    if not target_field:
        return queryset

    lookup = SEARCH_FIELD_CONFIG[target_field]["lookup"]
    comparator = "lt" if descending else "gt"
    cursor_target_value, cursor_id = _decode_cursor(cursor_value)

    if is_datetime_field(target_field):
        parsed = parse_datetime(cursor_target_value)
        if parsed is None:
            raise ValidationError("Cursor must be an ISO datetime for this sort field")
        if timezone.is_naive(parsed):
            parsed = timezone.make_aware(parsed)
        next_page_filter = Q(**{f"{lookup}__{comparator}": parsed})
        if cursor_id:
            next_page_filter |= Q(**{lookup: parsed}) & Q(
                **{f"id__{comparator}": cursor_id}
            )
        return queryset.filter(next_page_filter)

    next_page_filter = Q(**{f"{lookup}__{comparator}": cursor_target_value})
    if cursor_id:
        next_page_filter |= Q(**{lookup: cursor_target_value}) & Q(
            **{f"id__{comparator}": cursor_id}
        )
    return queryset.filter(next_page_filter)


def build_event_search_queryset(
    base_queryset: QuerySet, payload: dict[str, Any]
) -> tuple[QuerySet, dict[str, Any], list[str]]:
    """
    Build the event queryset based on validated search payload.

    Returns the queryset, meta info, and resolved ordering.
    """
    q_value = payload.get("q")
    filters = payload.get("filters", [])
    sort = payload.get("sort") or DEFAULT_SORT

    queryset, tokens = _apply_free_text(
        base_queryset.exclude(is_external=True), q_value
    )

    warnings: list[str] = []
    meta: dict[str, Any] = {
        "interpreted_as": "basic",
        "tokens": tokens,
        "warnings": warnings,
    }

    has_regex = False
    for filter_data in filters:
        clause, used_regex = _build_filter_clause(filter_data)
        queryset = queryset.filter(clause)
        has_regex = has_regex or used_regex

    ordering = _build_ordering(sort)
    queryset = queryset.order_by(*ordering).distinct()

    if has_regex:
        meta["interpreted_as"] = "regex"
        warnings.append(
            "Regex filters can be slow on large datasets. Consider using 'contains' for faster results."  # noqa: E501
        )
    elif filters:
        meta["interpreted_as"] = "advanced"
    elif q_value:
        meta["interpreted_as"] = "basic"

    return queryset, meta, ordering

