def get_google_refresh_client_credentials() -> tuple[str, str]:
    """
    Resolve OAuth client credentials for Google token refresh.

    Precedence:
    1. Dedicated calendar OAuth credentials
    2. Legacy login OAuth credentials
    3. allauth SocialApp credentials (transitional fallback)
    """
    calendar_client_id = str(
        getattr(settings, "GOOGLE_CALENDAR_OAUTH_CLIENT_ID", "") or ""
    )
    calendar_client_secret = str(
        getattr(settings, "GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET", "") or ""
    )
    if calendar_client_id and calendar_client_secret:
        return calendar_client_id, calendar_client_secret

    legacy_client_id = str(getattr(settings, "GOOGLE_CLIENT_ID", "") or "")
    legacy_client_secret = str(getattr(settings, "GOOGLE_CLIENT_SECRET", "") or "")
    if legacy_client_id and legacy_client_secret:
        return legacy_client_id, legacy_client_secret

    try:
        google_app = SocialApp.objects.get(provider="google")
    except SocialApp.DoesNotExist as exc:
        raise RuntimeError(
            "Google OAuth client credentials are not configured."
        ) from exc

    return google_app.client_id, google_app.secret


def _is_invalid_grant_error(error) -> bool:
    """Return True when Google reports an invalid_grant refresh failure."""

    error_message = str(error).lower()
    if "invalid_grant" in error_message:
        return True

    for arg in getattr(error, "args", ()):  # google auth often includes a dict payload
        if isinstance(arg, dict) and arg.get("error") == "invalid_grant":
            return True

    return False


def _disable_calendar_after_invalid_grant(calendar, error) -> str:
    """Disable sync and clear credentials after Google revokes access."""

    account_identifier = calendar.account_email or calendar.account_name or calendar.id
    logger.warning(
        "Google revoked access for calendar %s (%s). Disabling sync until the user reconnects. Error: %s",
        calendar.account_name,
        account_identifier,
        error,
    )

    calendar.access_token = ""
    calendar.refresh_token = ""
    calendar.token_expiry = None
    calendar.gcal_sync_token = None
    calendar.sync_enabled = False
    calendar.save(
        update_fields=[
            "_access_token",
            "_refresh_token",
            "token_expiry",
            "gcal_sync_token",
            "sync_enabled",
        ]
    )

    notification_message = (
        "We lost access to your Google calendar "
        f"({account_identifier}). Please reconnect this account to resume syncing."
    )
    try:
        NotificationService.create_notification(
            user=calendar.user,
            title="Google calendar sync disconnected",
            message=notification_message,
            notification_type="SYSTEM",
            source_object=calendar,
            priority="HIGH",
        )
    except Exception:  # Don't block sync logging if notifications fail
        logger.exception(
            "Failed to create notification for revoked Google calendar access"
        )

    return (
        "Google authorization for this calendar is no longer valid. "
        "Sync has been disabled; please reconnect this Google account to resume syncing."
    )


@shared_task
def sync_all_calendars():
    """
    Sync all external calendars that have sync enabled
    """
    logger.info("Starting sync for all calendars")
    calendars = ExternalCalendarAccount.objects.filter(
        is_active=True, sync_enabled=True
    )

    for calendar in calendars:
        sync_calendar.delay(calendar.id)

    return f"Scheduled sync for {calendars.count()} calendars"


def _build_google_service_for_external_account(calendar: ExternalCalendarAccount):
    client_id, client_secret = get_google_refresh_client_credentials()
    credentials = google.oauth2.credentials.Credentials(
        token=calendar.access_token,
        refresh_token=calendar.refresh_token,
        token_uri="https://oauth2.googleapis.com/token",
        client_id=client_id,
        client_secret=client_secret,
        scopes=["https://www.googleapis.com/auth/calendar"],
    )
    if not credentials.valid and credentials.refresh_token:
        credentials.refresh(google.auth.transport.requests.Request())
        calendar.access_token = credentials.token
        if credentials.refresh_token:
            calendar.refresh_token = credentials.refresh_token
        calendar.token_expiry = credentials.expiry
        calendar.save(update_fields=["_access_token", "_refresh_token", "token_expiry"])
    return build("calendar", "v3", credentials=credentials)


@shared_task
def register_google_calendar_watch(calendar_id):
    calendar = ExternalCalendarAccount.objects.get(id=calendar_id, provider="GOOGLE")
    service = _build_google_service_for_external_account(calendar)
    channel_id = str(uuid.uuid4())
    site_url = str(getattr(settings, "SITE_URL", "")).rstrip("/")
    response = (
        service.events()
        .watch(
            calendarId=calendar.calendar_id or "primary",
            body={
                "id": channel_id,
                "type": "web_hook",
                "address": f"{site_url}/api/calendar-connections/google/webhook/",
                "token": str(calendar.id),
            },
        )
        .execute()
    )
    expiration_ms = response.get("expiration")
    watch_expires_at = None
    if expiration_ms:
        watch_expires_at = datetime.fromtimestamp(
            int(expiration_ms) / 1000,
            tz=timezone.get_current_timezone(),
        )

    calendar.watch_channel_id = response.get("id", channel_id)
    calendar.watch_resource_id = response.get("resourceId", "")
    calendar.watch_expires_at = watch_expires_at
    calendar.save(
        update_fields=[
            "watch_channel_id",
            "watch_resource_id",
            "watch_expires_at",
            "updated_at",
        ]
    )
    return str(calendar.id)


@shared_task
def renew_google_calendar_watches():
    cutoff = timezone.now() + timedelta(days=1)
    calendars = ExternalCalendarAccount.objects.filter(
        models.Q(watch_expires_at__isnull=True)
        | models.Q(watch_expires_at__lte=cutoff),
        provider="GOOGLE",
        is_active=True,
        sync_enabled=True,
    )
    for calendar in calendars:
        register_google_calendar_watch.delay(calendar.id)
    return calendars.count()


@shared_task
def sync_apple_caldav_connection_task(connection_id, full_sync=False):
    from calendars.services.apple_caldav import sync_apple_caldav_connection

    return sync_apple_caldav_connection(str(connection_id), full_sync=full_sync)


@shared_task
def sync_event_to_connected_calendar(event_id):
    from calendars.services.apple_caldav import export_event_to_apple_caldav
    from events.models import Event

    try:
        event = Event.objects.get(pk=event_id, is_external=False)
    except Event.DoesNotExist:
        return None
    if not event.calendar_id:
        return None
    try:
        connected_calendar = ConnectedCalendar.objects.select_related("connection").get(
            pk=event.calendar_id,
            is_selected=True,
            supports_write=True,
            connection__provider="APPLE_ICLOUD",
        )
    except ConnectedCalendar.DoesNotExist:
        return None
    return export_event_to_apple_caldav(event, connected_calendar)


@shared_task
def sync_calendar(calendar_id):
    """
    Sync a specific external calendar.

    Broadcasts real-time sync status updates via WebSocket to connected clients.
    """
    from mobile.services.websocket_broadcast import broadcast_calendar_sync_status

    try:
        calendar = ExternalCalendarAccount.objects.get(id=calendar_id)

        # Skip if calendar is not active or sync is disabled
        if not calendar.is_active or not calendar.sync_enabled:
            logger.warning(
                f"Skipping sync for calendar {calendar_id} - not active or sync disabled"
            )
            return (
                f"Skipped sync for calendar {calendar_id} - not active or sync disabled"
            )

        logger.info(
            f"Starting sync for calendar {calendar_id} ({calendar.account_name})"
        )

        # Broadcast sync started via WebSocket
        family_id = None
        if hasattr(calendar.user, "profile") and calendar.user.profile.primary_family:
            family_id = str(calendar.user.profile.primary_family.id)
        elif calendar.user.family_memberships.exists():
            first_membership = calendar.user.family_memberships.first()
            if first_membership:
                family_id = str(first_membership.family.id)

        if family_id:
            broadcast_calendar_sync_status(
                family_id=family_id,
                calendar_id=str(calendar_id),
                status="started",
                progress=0,
            )

        # Create a sync log entry
        sync_log = SyncLog.objects.create(
            calendar=calendar,
            status="SUCCESS",  # Will be updated after sync
            events_added=0,
            events_updated=0,
            events_deleted=0,
            events_skipped=0,
        )

        # Get lists of deleted and modified events
        deleted_event_ids = set(
            calendar.deleted_events.values_list("external_id", flat=True)
        )
        modified_events = {
            me.external_id: me.event for me in calendar.modified_events.all()
        }

        # Log the skipped events based on locally deleted/modified records
        sync_log.events_skipped = len(deleted_event_ids) + len(modified_events)

        # Get user's timezone from their profile, fallback to default if not set
        user_tz = timezone.get_default_timezone()
        if hasattr(calendar.user, "profile") and calendar.user.profile.timezone:
            try:
                user_tz = pytz.timezone(calendar.user.profile.timezone)  # type: ignore[assignment]
            except pytz.exceptions.UnknownTimeZoneError:
                logger.warning(
                    f"Unknown timezone '{calendar.user.profile.timezone}' for user {calendar.user.username}, using default"
                )

        external_events_data = []
        fetch_error = None

        # --- Fetch and Parse ICS Data ---
        if calendar.ical_url:
            logger.info(f"Fetching ICS data from {calendar.ical_url}")
            try:
                validated_url = normalize_and_validate_ics_url(calendar.ical_url)
                if validated_url is None:
                    raise requests.RequestException(
                        f"ICS URL failed SSRF validation: {calendar.ical_url}"
                    )
                response = _request_with_redirect_guard(
                    method="GET",
                    initial_url=validated_url,
                    timeout=30,
                )
                if response is None:
                    raise requests.RequestException(
                        "ICS fetch blocked by redirect guard"
                    )
                response.raise_for_status()
                ics_data = response.text

                # Parse the ICS data
                try:
                    gcal = iCalCalendar.from_ical(ics_data)
                    for component in gcal.walk():
                        if component.name == "VEVENT":
                            uid = component.get("uid")
                            if not uid:
                                logger.warning(
                                    f"Calendar {calendar.id}: Skipping VEVENT without UID"
                                )
                                continue

                            # Get dtstart (required per RFC 5545)
                            dtstart_obj = component.get("dtstart")
                            if not dtstart_obj:
                                logger.warning(
                                    f"Calendar {calendar.id}: Skipping VEVENT {uid}: missing required dtstart"
                                )
                                continue

                            # Try to extract dtstart value safely
                            try:
                                dtstart = dtstart_obj.dt
                            except (AttributeError, ValueError) as e:
                                logger.warning(
                                    f"Calendar {calendar.id}: Skipping VEVENT {uid}: invalid dtstart format - {e}"
                                )
                                continue

                            # Get dtend or duration (RFC 5545 allows DURATION instead of DTEND)
                            dtend_obj = component.get("dtend")
                            duration_obj = component.get("duration")

                            if dtend_obj:
                                # Event has explicit end time
                                try:
                                    dtend = dtend_obj.dt
                                except (AttributeError, ValueError) as e:
                                    logger.warning(
                                        f"Calendar {calendar.id}: Skipping VEVENT {uid}: invalid dtend format - {e}"
                                    )
                                    continue
                            elif duration_obj:
                                # Event has duration instead of end time
                                try:
                                    # Calculate end time from start + duration
                                    duration = duration_obj.dt
                                    if isinstance(dtstart, date) and not isinstance(
                                        dtstart, datetime
                                    ):
                                        # For all-day events with duration
                                        dtend = dtstart + duration
                                    else:
                                        # For timed events with duration
                                        dtend = dtstart + duration
                                except (AttributeError, ValueError, TypeError) as e:
                                    logger.warning(
                                        f"Calendar {calendar.id}: Skipping VEVENT {uid}: invalid duration format - {e}"
                                    )
                                    continue
                            else:
                                # No end time or duration specified
                                # Per RFC 5545, if dtstart is a DATE (all-day), default duration is 1 day
                                # If dtstart is a DATE-TIME, the event has zero duration (instant event)
                                if isinstance(dtstart, date) and not isinstance(
                                    dtstart, datetime
                                ):
                                    # All-day event without explicit end - default to 1 day
                                    dtend = dtstart + timedelta(days=1)
                                else:
                                    # Instant event (zero duration)
                                    dtend = dtstart

                            if isinstance(dtstart, datetime) and timezone.is_naive(
                                dtstart
                            ):
                                dtstart = timezone.make_aware(
                                    dtstart, user_tz
                                )  # Use user's timezone
                            elif not isinstance(
                                dtstart, datetime
                            ):  # Handle date objects if necessary
                                dtstart = timezone.make_aware(
                                    datetime.combine(dtstart, datetime.min.time()),
                                    user_tz,
                                )

                            if isinstance(dtend, datetime) and timezone.is_naive(dtend):
                                dtend = timezone.make_aware(dtend, user_tz)
                            elif not isinstance(dtend, datetime):
                                dtend = timezone.make_aware(
                                    datetime.combine(dtend, datetime.min.time()),
                                    user_tz,
                                )

                            # Filter out events that start before the calendar was connected
                            # This ensures we only sync future events from the connection date
                            if dtstart < calendar.created_at:
                                logger.debug(
                                    f"Skipping past event {uid} with start time {dtstart} (before calendar creation {calendar.created_at})"
                                )
                                continue

                            external_events_data.append(
                                {
                                    "external_id": str(uid),
                                    "title": str(component.get("summary", "")),
                                    "description": str(
                                        component.get("description", "")
                                    ),
                                    "location": str(component.get("location", "")),
                                    "start_time": dtstart,
                                    "end_time": dtend,
                                }
                            )
                    logger.info(
                        f"Parsed {len(external_events_data)} events from ICS feed."
                    )

                except ValueError as e:
                    fetch_error = f"Error parsing ICS data: {str(e)}"
                    logger.error(
                        f"Error parsing ICS data for calendar {calendar_id}: {fetch_error}"
                    )
                except Exception as e:  # Catch other potential parsing errors
                    fetch_error = f"Unexpected error parsing ICS data: {str(e)}"
                    logger.exception(
                        f"Unexpected error parsing ICS data for calendar {calendar_id}"
                    )

            except requests.exceptions.RequestException as e:
                fetch_error = f"Error fetching ICS URL: {str(e)}"
                logger.error(
                    f"Error fetching ICS URL for calendar {calendar_id}: {fetch_error}"
                )
            except Exception as e:  # Catch other unexpected errors during fetch
                fetch_error = f"Unexpected error fetching ICS URL: {str(e)}"
                logger.exception(
                    f"Unexpected error fetching ICS URL for calendar {calendar_id}"
                )

        elif calendar.provider == "GOOGLE":
            # --- Google Calendar API Fetching ---
            logger.info(f"Fetching Google Calendar data for {calendar.account_name}")
            if not calendar.refresh_token:
                fetch_error = "Missing Google refresh token."
                logger.error(  # Corrected indentation
                    f"Missing refresh token for Google account {calendar_id} ({calendar.account_name})"
                )
            else:
                try:
                    try:
                        client_id, client_secret = (
                            get_google_refresh_client_credentials()
                        )
                    except RuntimeError as credential_error:
                        fetch_error = str(credential_error)
                        logger.error(fetch_error)
                        # Update sync log and return early
                        sync_log.status = "FAILED"
                        sync_log.error_message = fetch_error
                        sync_log.completed_at = timezone.now()
                        sync_log.save()
                        return f"Failed sync for calendar {calendar_id}: {fetch_error}"

                    # Create credentials object from stored tokens and fetched app credentials
                    credentials = google.oauth2.credentials.Credentials(
                        token=calendar.access_token,
                        refresh_token=calendar.refresh_token,
                        token_uri="https://oauth2.googleapis.com/token",
                        client_id=client_id,
                        client_secret=client_secret,
                        scopes=["https://www.googleapis.com/auth/calendar.readonly"],
                    )

                    # Refresh token if expired or close to expiry
                    if not credentials.valid or (
                        credentials.expiry
                        and credentials.expiry < timezone.now() + timedelta(minutes=5)
                    ):
                        logger.info(
                            f"Refreshing Google access token for {calendar.account_name}"
                        )
                        try:
                            request = google.auth.transport.requests.Request()
                            credentials.refresh(request)
                            # Save the potentially updated tokens back to the model
                            calendar.access_token = credentials.token
                            calendar.refresh_token = (
                                credentials.refresh_token
                            )  # Refresh token might change
                            calendar.token_expiry = credentials.expiry
                            calendar.save(
                                update_fields=[
                                    "_access_token",
                                    "_refresh_token",
                                    "token_expiry",
                                ]
                            )
                            logger.info(
                                f"Successfully refreshed Google token for {calendar.account_name}"
                            )
                        except RefreshError as refresh_error:
                            if _is_invalid_grant_error(refresh_error):
                                fetch_error = _disable_calendar_after_invalid_grant(
                                    calendar, refresh_error
                                )
                            else:
                                fetch_error = f"Failed to refresh Google token: {str(refresh_error)}"
                                logger.exception(
                                    f"Failed to refresh Google token for {calendar.account_name}"
                                )
                        except Exception as refresh_error:
                            fetch_error = (
                                f"Failed to refresh Google token: {str(refresh_error)}"
                            )
                            logger.exception(
                                f"Failed to refresh Google token for {calendar.account_name}"
                            )

                    if not fetch_error:  # Proceed only if token refresh didn't fail
                        service = build("calendar", "v3", credentials=credentials)
                        sync_token = calendar.gcal_sync_token
                        page_token = None
                        gcal_events = []
                        retried_after_410 = False

                        # For initial sync (no sync token), only fetch events from connection date forward
                        # Use the calendar's created_at date as the starting point
                        remote_calendar_id = calendar.calendar_id or "primary"
                        list_params = {
                            "calendarId": remote_calendar_id,
                            "showDeleted": True,  # Important to detect deletions
                            "singleEvents": True,  # Expand recurring events
                            "orderBy": "startTime",  # Recommended for singleEvents
                        }

                        # Only add timeMin for initial sync (when there's no sync token)
                        # For incremental syncs with syncToken, we need all changes including deletions
                        if not sync_token:
                            # Use calendar creation date as the starting point for sync
                            time_min = calendar.created_at.isoformat()
                            list_params["timeMin"] = time_min
                            logger.info(
                                f"Initial sync for {calendar.account_name} - fetching events from {time_min} forward"
                            )

                        while True:
                            try:
                                # Add pagination and sync token parameters
                                if page_token:
                                    list_params["pageToken"] = page_token
                                elif sync_token:
                                    list_params["syncToken"] = sync_token

                                events_result = (
                                    service.events().list(**list_params).execute()
                                )
                                gcal_events.extend(events_result.get("items", []))
                                page_token = events_result.get("nextPageToken")
                                if not page_token:
                                    # Store the next sync token after processing all pages
                                    next_sync_token = events_result.get("nextSyncToken")
                                    if next_sync_token:
                                        calendar.gcal_sync_token = next_sync_token
                                        calendar.save(update_fields=["gcal_sync_token"])
                                        logger.info(
                                            f"Stored next sync token for {calendar.account_name}"
                                        )
                                    else:
                                        # This might happen on initial sync or if no changes
                                        logger.warning(
                                            f"No nextSyncToken received for {calendar.account_name}. Full sync might be needed next time."
                                        )
                                        # Consider clearing the stored sync token if this indicates an issue
                                        # calendar.gcal_sync_token = None
                                        # calendar.save(update_fields=['gcal_sync_token'])
                                    break  # Exit loop after last page
                                else:
                                    # If paginating, clear sync_token for subsequent page requests
                                    if "syncToken" in list_params:
                                        del list_params["syncToken"]

                            except RefreshError as refresh_error:
                                if _is_invalid_grant_error(refresh_error):
                                    fetch_error = _disable_calendar_after_invalid_grant(
                                        calendar, refresh_error
                                    )
                                else:
                                    fetch_error = f"Unexpected Google auth error while fetching events: {str(refresh_error)}"
                                    logger.exception(
                                        f"Unexpected Google auth error for {calendar.account_name}"
                                    )
                                break  # Exit pagination loop
                            except HttpError as error:
                                if error.resp.status == 410:  # Sync token invalid
                                    logger.warning(
                                        f"Google sync token invalid for {calendar.account_name}. Retrying full sync."
                                    )
                                    if retried_after_410:
                                        fetch_error = "Google sync token invalid after full retry."
                                        break
                                    calendar.gcal_sync_token = (
                                        None  # Clear invalid token
                                    )
                                    calendar.save(update_fields=["gcal_sync_token"])
                                    sync_token = None
                                    page_token = None
                                    gcal_events = []
                                    retried_after_410 = True
                                    list_params.pop("syncToken", None)
                                    list_params.pop("pageToken", None)
                                    list_params["timeMin"] = (
                                        calendar.created_at.isoformat()
                                    )
                                    continue
                                else:
                                    fetch_error = f"Google API error: {str(error)}"
                                    logger.exception(
                                        f"Google API error for {calendar.account_name}"
                                    )
                                    break  # Exit pagination loop
                            except Exception as e:
                                fetch_error = (
                                    f"Unexpected error fetching Google events: {str(e)}"
                                )
                                logger.exception(
                                    f"Unexpected error fetching Google events for {calendar.account_name}"
                                )
                                break  # Exit pagination loop

                        if not fetch_error:
                            # Process fetched Google events
                            for item in gcal_events:
                                status = item.get("status")
                                if status == "cancelled":
                                    # Handle deletion later in the sync process
                                    continue

                                # Parse start/end times carefully
                                start_data = item.get("start")
                                end_data = item.get("end")
                                start_time = None
                                end_time = None

                                if start_data:
                                    start_str = start_data.get(
                                        "dateTime"
                                    ) or start_data.get("date")
                                    if start_str:
                                        try:
                                            start_time = dateutil.parser.isoparse(
                                                start_str
                                            )
                                            # Make timezone-aware if naive
                                            if timezone.is_naive(start_time):
                                                # Google 'date' objects are timezone naive, use user's timezone
                                                start_time = timezone.make_aware(
                                                    start_time,
                                                    user_tz,
                                                )
                                        except ValueError:
                                            logger.warning(
                                                f"Could not parse start time: {start_str}"
                                            )

                                if end_data:
                                    end_str = end_data.get("dateTime") or end_data.get(
                                        "date"
                                    )
                                    if end_str:
                                        try:
                                            end_time = dateutil.parser.isoparse(end_str)
                                            if timezone.is_naive(end_time):
                                                # Handle date objects - use user's timezone
                                                end_time = timezone.make_aware(
                                                    end_time,
                                                    user_tz,
                                                )
                                                # If it was a 'date' object, it represents the whole day.
                                                # Google API might return the *start* of the next day for all-day events.
                                                # Adjusting might be complex, consider how Event model handles all-day.
                                        except ValueError:
                                            logger.warning(
                                                f"Could not parse end time: {end_str}"
                                            )

                                # Skip if essential times are missing
                                if not start_time or not end_time:
                                    logger.warning(
                                        f"Skipping event {item.get('id')} due to missing/unparseable start/end time."
                                    )
                                    continue

                                external_events_data.append(
                                    {
                                        "external_id": item.get("id"),
                                        "title": item.get("summary", ""),
                                        "description": item.get("description", ""),
                                        "location": item.get("location", ""),
                                        "start_time": start_time,
                                        "end_time": end_time,
                                        "status": status,  # Keep status for deletion check later
                                        # Add other relevant fields if needed
                                    }
                                )
                            logger.info(
                                f"Processed {len(external_events_data)} events from Google Calendar."
                            )

                except Exception as e:
                    fetch_error = f"Error setting up Google API client: {str(e)}"
                    logger.exception(
                        f"Error setting up Google API client for {calendar.account_name}"
                    )
            # --- End Google Calendar API Fetching ---
        else:
            fetch_error = f"Sync not supported for provider {calendar.provider} without an ICS URL."
            logger.warning(
                f"Sync not supported for calendar {calendar_id}: Provider {calendar.provider}, no ICS URL."
            )
        # --- End Fetch and Parse ---

        # If fetching failed, log the error and exit gracefully
        if fetch_error:
            sync_log.status = "FAILED"
            sync_log.error_message = fetch_error
            sync_log.completed_at = timezone.now()
            sync_log.save()
            return f"Failed sync for calendar {calendar_id}: {fetch_error}"

        processed_external_ids = set()
        events_added_count = 0
        events_updated_count = 0
        events_deleted_count = 0

        with transaction.atomic():
            # Get existing internal events linked to this ExternalCalendarAccount
            # Use calendar_id field on Event which should store ExternalCalendarAccount.id
            # Filter by provider as well to be safe
            internal_events_qs = Event.objects.filter(
                is_external=True,
                calendar_id=str(calendar.id),
                external_source=calendar.provider,  # Ensure we only match events from this source
            )
            # Create a dictionary mapping external_id to Event instances
            internal_events = {event.external_id: event for event in internal_events_qs}

            # Store Google event statuses for deletion check
            google_event_statuses = {
                ev["external_id"]: ev.get("status")
                for ev in external_events_data
                if "external_id" in ev
            }

            for ext_event_data in external_events_data:
                ext_id = ext_event_data.get("external_id")
                if not ext_id:
                    logger.warning(
                        f"Skipping external event data with no ID: {ext_event_data.get('title')}"
                    )
                    continue

                # Skip cancelled events here, handle deletion later based on comparison
                if ext_event_data.get("status") == "cancelled":
                    continue

                processed_external_ids.add(ext_id)

                # Skip if event was deleted locally
                if ext_id in deleted_event_ids:
                    continue

                # Skip if event was modified locally (optional, based on desired behavior)
                # if ext_id in modified_events:
                #     continue

                internal_event = internal_events.get(str(ext_id))

                if internal_event:
                    # Event exists internally, check for updates
                    updated = False
                    update_fields = []

                    # Compare relevant fields
                    # Use .get() with default to handle potentially missing fields in ICS
                    if internal_event.title != ext_event_data.get("title"):
                        internal_event.title = str(ext_event_data.get("title", ""))
                        updated = True
                        update_fields.append("title")
                    if internal_event.description != ext_event_data.get("description"):
                        internal_event.description = str(
                            ext_event_data.get("description", "")
                        )
                        updated = True
                        update_fields.append("description")
                    if internal_event.location != ext_event_data.get("location"):
                        internal_event.location = str(
                            ext_event_data.get("location", "")
                        )
                        updated = True
                        update_fields.append("location")
                    # Sync event_status from external source
                    ext_status = ext_event_data.get("status", "confirmed")
                    new_event_status = (
